messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Low Poly Treadmill</title>
    <style>
        body { margin: 0; overflow: hidden; background: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="importmap">
{
    "imports": {
        "three": "./three.module.js"
    }
}
</script>
<script type="module">
import * as THREE from './three.module.js';

const clock = new THREE.Clock();

// --- Scene ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x202025);
scene.fog = new THREE.Fog(0x202025, 10, 25);

// --- Camera ---
const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(5, 3, 8);
camera.lookAt(0, 1.5, 0);

// --- Renderer ---
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// --- Lights ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(3, 8, 5);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
dirLight.shadow.camera.near = 0.5;
dirLight.shadow.camera.far = 20;
dirLight.shadow.camera.left = -5;
dirLight.shadow.camera.right = 5;
dirLight.shadow.camera.top = 5;
dirLight.shadow.camera.bottom = -5;
scene.add(dirLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 0.3);
fillLight.position.set(-3, 2, -5);
scene.add(fillLight);

// --- Treadmill ---
const treadmillGroup = new THREE.Group();
scene.add(treadmillGroup);

// Belt
const beltGeo = new THREE.BoxGeometry(6, 0.1, 1.5);
const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9 });
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.position.y = 0.05;
belt.receiveShadow = true;
treadmillGroup.add(belt);

// Belt lines (moving indicator)
const lineGeo = new THREE.BoxGeometry(0.02, 0.12, 1.3);
const lineMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
const beltLines = [];
for (let i = 0; i < 12; i++) {
    const line = new THREE.Mesh(lineGeo, lineMat);
    line.position.set(-2.5 + i * 0.5, 0.07, 0);
    treadmillGroup.add(line);
    beltLines.push(line);
}

// Side rails
const railGeo = new THREE.BoxGeometry(6.2, 0.08, 0.08);
const railMat = new THREE.MeshStandardMaterial({ color: 0x555555, metalness: 0.5 });
const railL = new THREE.Mesh(railGeo, railMat);
railL.position.set(0, 0.12, 0.78);
treadmillGroup.add(railL);
const railR = new THREE.Mesh(railGeo, railMat);
railR.position.set(0, 0.12, -0.78);
treadmillGroup.add(railR);

// End rollers
const rollerGeo = new THREE.CylinderGeometry(0.12, 0.12, 6.2, 8);
const rollerMat = new THREE.MeshStandardMaterial({ color: 0x444444, metalness: 0.6 });
const rollerL = new THREE.Mesh(rollerGeo, rollerMat);
rollerL.rotation.z = Math.PI / 2;
rollerL.position.set(0, 0.12, 0.78);
treadmillGroup.add(rollerL);
const rollerR = new THREE.Mesh(rollerGeo, rollerMat);
rollerR.rotation.z = Math.PI / 2;
rollerR.position.set(0, 0.12, -0.78);
treadmillGroup.add(rollerR);

// Support legs
const legGeo = new THREE.BoxGeometry(0.15, 0.5, 0.15);
const legMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
const legPositions = [[-2.8, 0.3, 0.6], [-2.8, 0.3, -0.6], [2.8, 0.3, 0.6], [2.8, 0.3, -0.6]];
legPositions.forEach(pos => {
    const leg = new THREE.Mesh(legGeo, legMat);
    leg.position.set(...pos);
    leg.castShadow = true;
    treadmillGroup.add(leg);
});

// --- Humanoid Figure ---
const humanoid = new THREE.Group();
scene.add(humanoid);

const skinColor = 0xd4956b;
const shirtColor = 0x3366aa;
const pantsColor = 0x2a2a3a;
const shoeColor = 0x553322;

const skinMat = new THREE.MeshStandardMaterial({ color: skinColor, roughness: 0.7 });
const shirtMat = new THREE.MeshStandardMaterial({ color: shirtColor, roughness: 0.6 });
const pantsMat = new THREE.MeshStandardMaterial({ color: pantsColor, roughness: 0.7 });
const shoeMat = new THREE.MeshStandardMaterial({ color: shoeColor, roughness: 0.8 });

// Helper to create limb with pivot
function createLimb(geo, mat, pivotOffset) {
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true;
    const pivot = new THREE.Group();
    pivot.add(mesh);
    mesh.position.copy(pivotOffset);
    return pivot;
}

// --- Body parts ---
// Torso
const torsoGeo = new THREE.BoxGeometry(0.5, 0.7, 0.3);
const torso = new THREE.Mesh(torsoGeo, shirtMat);
torso.position.y = 1.55;
torso.castShadow = true;
humanoid.add(torso);

// Head
const headGeo = new THREE.BoxGeometry(0.3, 0.3, 0.28);
const head = new THREE.Mesh(headGeo, skinMat);
head.position.y = 2.1;
head.castShadow = true;
humanoid.add(head);

// Neck
const neckGeo = new THREE.BoxGeometry(0.15, 0.12, 0.15);
const neck = new THREE.Mesh(neckGeo, skinMat);
neck.position.y = 1.9;
humanoid.add(neck);

// Right Upper Arm
const rUpperArmPivot = createLimb(
    new THREE.BoxGeometry(0.15, 0.35, 0.15),
    shirtMat,
    new THREE.Vector3(0, -0.15, 0)
);
rUpperArmPivot.position.set(0.35, 1.82, 0);
humanoid.add(rUpperArmPivot);

// Right Lower Arm
const rLowerArmPivot = createLimb(
    new THREE.BoxGeometry(0.13, 0.3, 0.13),
    skinMat,
    new THREE.Vector3(0, -0.15, 0)
);
rLowerArmPivot.position.set(0, -0.18, 0);
rUpperArmPivot.add(rLowerArmPivot);

// Right Hand
const rHand = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.12), skinMat);
rHand.position.set(0, -0.32, 0);
rLowerArmPivot.add(rHand);

// Left Upper Arm
const lUpperArmPivot = createLimb(
    new THREE.BoxGeometry(0.15, 0.35, 0.15),
    shirtMat,
    new THREE.Vector3(0, -0.15, 0)
);
lUpperArmPivot.position.set(-0.35, 1.82, 0);
humanoid.add(lUpperArmPivot);

// Left Lower Arm
const lLowerArmPivot = createLimb(
    new THREE.BoxGeometry(0.13, 0.3, 0.13),
    skinMat,
    new THREE.Vector3(0, -0.15, 0)
);
lLowerArmPivot.position.set(0, -0.18, 0);
lUpperArmPivot.add(lLowerArmPivot);

// Left Hand
const lHand = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.12), skinMat);
lHand.position.set(0, -0.32, 0);
lLowerArmPivot.add(lHand);

// Right Upper Leg
const rUpperLegPivot = createLimb(
    new THREE.BoxGeometry(0.18, 0.4, 0.18),
    pantsMat,
    new THREE.Vector3(0, -0.2, 0)
);
rUpperLegPivot.position.set(0.12, 1.18, 0);
humanoid.add(rUpperLegPivot);

// Right Lower Leg
const rLowerLegPivot = createLimb(
    new THREE.BoxGeometry(0.15, 0.35, 0.15),
    pantsMat,
    new THREE.Vector3(0, -0.18, 0)
);
rLowerLegPivot.position.set(0, -0.4, 0);
rUpperLegPivot.add(rLowerLegPivot);

// Right Shoe
const rShoe = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.1, 0.25), shoeMat);
rShoe.position.set(0, -0.37, 0.04);
rLowerLegPivot.add(rShoe);

// Left Upper Leg
const lUpperLegPivot = createLimb(
    new THREE.BoxGeometry(0.18, 0.4, 0.18),
    pantsMat,
    new THREE.Vector3(0, -0.2, 0)
);
lUpperLegPivot.position.set(-0.12, 1.18, 0);
humanoid.add(lUpperLegPivot);

// Left Lower Leg
const lLowerLegPivot = createLimb(
    new THREE.BoxGeometry(0.15, 0.35, 0.15),
    pantsMat,
    new THREE.Vector3(0, -0.18, 0)
);
lLowerLegPivot.position.set(0, -0.4, 0);
lUpperLegPivot.add(lLowerLegPivot);

// Left Shoe
const lShoe = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.1, 0.25), shoeMat);
lShoe.position.set(0, -0.37, 0.04);
lLowerLegPivot.add(lShoe);

// --- Animation State Machine ---
// Cycle: 0-2s stand, 2-5s walk, 5-8s run, 8-10s stand
const CYCLE_DURATION = 10.0;

function getPhase(t) {
    const cycleT = t % CYCLE_DURATION;
    if (cycleT < 2.0) return 'stand';
    if (cycleT < 5.0) return 'walk';
    if (cycleT < 8.0) return 'run';
    return 'stand';
}

function lerpAngle(current, target, speed) {
    return current + (target - current) * Math.min(speed, 1);
}

// --- Animation ---
let prevTime = 0;
let torsoRotX = 0;
let torsoRotZ = 0;
let headRotX = 0;
let torsoY = 1.55;
let headY = 2.1;

function animateHumanoid(time) {
    const phase = getPhase(time);
    const dt = clock.getDelta();

    // Belt animation
    beltLines.forEach(line => {
        line.position.x -= dt * (phase === 'run' ? 4 : phase === 'walk' ? 1.5 : 0);
        if (line.position.x < -3) line.position.x += 6;
    });

    switch (phase) {
        case 'stand': {
            // Smoothly return to neutral
            const standSpeed = 4.0;
            torsoRotX = lerpAngle(torsoRotX, 0, standSpeed * dt);
            torsoRotZ = lerpAngle(torsoRotZ, 0, standSpeed * dt);
            headRotX = lerpAngle(headRotX, 0, standSpeed * dt);
            torsoY = lerpAngle(torsoY, 1.55, standSpeed * dt);
            headY = lerpAngle(headY, 2.1, standSpeed * dt);

            // Arms hang at sides
            rUpperArmPivot.rotation.x = lerpAngle(rUpperArmPivot.rotation.x, 0, standSpeed * dt);
            lUpperArmPivot.rotation.x = lerpAngle(lUpperArmPivot.rotation.x, 0, standSpeed * dt);
            rLowerArmPivot.rotation.x = lerpAngle(rLowerArmPivot.rotation.x, 0, standSpeed * dt);
            lLowerArmPivot.rotation.x = lerpAngle(lLowerArmPivot.rotation.x, 0, standSpeed * dt);
            rHand.rotation.x = lerpAngle(rHand.rotation.x, 0, standSpeed * dt);
            lHand.rotation.x = lerpAngle(lHand.rotation.x, 0, standSpeed * dt);

            // Legs straight
            rUpperLegPivot.rotation.x = lerpAngle(rUpperLegPivot.rotation.x, 0, standSpeed * dt);
            lUpperLegPivot.rotation.x = lerpAngle(lUpperLegPivot.rotation.x, 0, standSpeed * dt);
            rLowerLegPivot.rotation.x = lerpAngle(rLowerLegPivot.rotation.x, 0, standSpeed * dt);
            lLowerLegPivot.rotation.x = lerpAngle(lLowerLegPivot.rotation.x, 0, standSpeed * dt);
            break;
        }

        case 'walk': {
            // Walking: moderate pace, arms swing opposite to legs
            const walkCycle = time * 2.5; // walking speed
            const walkAmp = 0.55; // arm/leg swing amplitude

            // Torso: slight forward lean, gentle bob
            torsoRotX = 0.15 + Math.sin(walkCycle * 0.5) * 0.02;
            torsoRotZ = Math.sin(walkCycle * 0.5) * 0.03;
            torsoY = 1.55 + Math.abs(Math.sin(walkCycle)) * 0.03;
            headY = 2.1 + Math.abs(Math.sin(walkCycle)) * 0.03;
            headRotX = Math.sin(walkCycle * 0.5) * 0.03;

            // Arms swing
            const armAngle = Math.sin(walkCycle) * walkAmp;
            rUpperArmPivot.rotation.x = lerpAngle(rUpperArmPivot.rotation.x, armAngle, 8 * dt);
            lUpperArmPivot.rotation.x = lerpAngle(lUpperArmPivot.rotation.x, -armAngle, 8 * dt);
            rLowerArmPivot.rotation.x = lerpAngle(rLowerArmPivot.rotation.x, 0.3 + Math.max(0, -Math.sin(walkCycle)) * 0.4, 6 * dt);
            lLowerArmPivot.rotation.x = lerpAngle(lLowerArmPivot.rotation.x, 0.3 + Math.max(0, Math.sin(walkCycle)) * 0.4, 6 * dt);

            // Legs swing
            const legAngle = Math.sin(walkCycle + Math.PI) * 0.6;
            rUpperLegPivot.rotation.x = lerpAngle(rUpperLegPivot.rotation.x, legAngle, 8 * dt);
            lUpperLegPivot.rotation.x = lerpAngle(lUpperLegPivot.rotation.x, -legAngle, 8 * dt);
            // Knee bend when leg swings back
            rLowerLegPivot.rotation.x = lerpAngle(rLowerLegPivot.rotation.x, Math.max(0, -Math.sin(walkCycle + Math.PI)) * 0.7, 6 * dt);
            lLowerLegPivot.rotation.x = lerpAngle(lLowerLegPivot.rotation.x, Math.max(0, Math.sin(walkCycle + Math.PI)) * 0.7, 6 * dt);
            break;
        }

        case 'run': {
            // Running: fast, large swings, significant forward lean
            const runCycle = time * 5.5; // faster pace
            const runAmp = 1.0; // larger amplitude

            // Torso: pronounced forward lean
            torsoRotX = 0.35 + Math.sin(runCycle * 0.5) * 0.03;
            torsoRotZ = Math.sin(runCycle * 0.5) * 0.05;
            torsoY = 1.55 + Math.abs(Math.sin(runCycle)) * 0.06;
            headY = 2.1 + Math.abs(Math.sin(runCycle)) * 0.06;
            headRotX = 0.1 + Math.sin(runCycle * 0.5) * 0.04;

            // Arms: pump vigorously
            const armAngle = Math.sin(runCycle) * runAmp;
            rUpperArmPivot.rotation.x = lerpAngle(rUpperArmPivot.rotation.x, armAngle, 10 * dt);
            lUpperArmPivot.rotation.x = lerpAngle(lUpperArmPivot.rotation.x, -armAngle, 10 * dt);
            // Elbows bent more, hands come up
            rLowerArmPivot.rotation.x = lerpAngle(rLowerArmPivot.rotation.x, 1.2 + Math.max(0, -Math.sin(runCycle)) * 0.5, 8 * dt);
            lLowerArmPivot.rotation.x = lerpAngle(lLowerArmPivot.rotation.x, 1.2 + Math.max(0, Math.sin(runCycle)) * 0.5, 8 * dt);

            // Legs: large strides, high knee lift
            const legAngle = Math.sin(runCycle + Math.PI) * runAmp;
            rUpperLegPivot.rotation.x = lerpAngle(rUpperLegPivot.rotation.x, legAngle, 10 * dt);
            lUpperLegPivot.rotation.x = lerpAngle(lUpperLegPivot.rotation.x, -legAngle, 10 * dt);
            // Knee bend much more pronounced
            rLowerLegPivot.rotation.x = lerpAngle(rLowerLegPivot.rotation.x, Math.max(0, -Math.sin(runCycle + Math.PI)) * 1.3, 8 * dt);
            lLowerLegPivot.rotation.x = lerpAngle(lLowerLegPivot.rotation.x, Math.max(0, Math.sin(runCycle + Math.PI)) * 1.3, 8 * dt);
            break;
        }
    }

    // Apply torso rotation to all child parts (except the torso itself which is directly on humanoid)
    // Actually, let's keep torso as a separate mesh and rotate it, then all appendages follow
    // The humanoid group rotation is already handled per-limb, but let's apply torso rotation to all appendages
    // We'll use a parent-child approach: make all limbs children of a "body" group that rotates with torso
    // For simplicity, let's just apply the torso rotations to the humanoid group's children
    // Actually the simplest: rotate humanoid itself for torso lean, and each limb has its own pivot
    // Let's just apply torsoRotX/Z to humanoid rotation
    humanoid.rotation.x = torsoRotX;
    humanoid.rotation.z = torsoRotZ;
}

// --- Ground plane ---
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.95 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.4;
ground.receiveShadow = true;
scene.add(ground);

// --- Wall / Background ---
const wallGeo = new THREE.PlaneGeometry(30, 10);
const wallMat = new THREE.MeshStandardMaterial({ color: 0x252530, roughness: 0.9 });
const wall = new THREE.Mesh(wallGeo, wallMat);
wall.position.set(0, 5, -5);
scene.add(wall);

// --- Resize ---
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// --- Main Loop ---
function animate() {
    requestAnimationFrame(animate);
    const time = clock.getElapsedTime();
    animateHumanoid(time);
    renderer.render(scene, camera);
}

// Start immediately
animate();

</script>
</body>
</html>
```
